#include "AccessCacheFormat.h"

// Compile-time checks of the offline schedule copy: a copy generated by the
// backend test fixture (backend/tests/door_access_cache_test.php <path>) is
// parsed and decided exactly as the controller does. Nothing reaches the
// firmware image.
namespace {
    using namespace DoorAccessCache;

    // Generated by backend/tests/door_access_cache_test.php (build at 2026-11-12 07:00 Asia/Manila).
    constexpr uint8_t SAMPLE[] = {
        0x45, 0x4E, 0x41, 0x43, 0x01, 0x00, 0x28, 0x00, 0x7B, 0x98, 0xCD, 0x80, 0x70, 0xF3, 0xF4, 0x6A,
        0x00, 0x91, 0xF4, 0x6A, 0x00, 0x1D, 0xFF, 0x6A, 0x04, 0x00, 0x06, 0x00, 0x05, 0x00, 0x00, 0x00,
        0x93, 0x70, 0xC0, 0x72, 0xB4, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x01, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00,
        0x02, 0x00, 0x00, 0x00, 0x02, 0x00, 0x01, 0x00, 0x04, 0x00, 0x00, 0x00, 0x03, 0x00, 0x00, 0x00,
        0x04, 0x01, 0x05, 0x00, 0x00, 0x00, 0x00, 0x00, 0x01, 0x00, 0x07, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x02, 0x00, 0x02, 0x01, 0x00, 0x00, 0x77, 0x00, 0x00, 0x00, 0x77, 0x00, 0x00, 0x00,
        0x02, 0x01, 0x00, 0x00, 0x99, 0x00, 0x00, 0x00, 0x99, 0x00, 0x00, 0x00, 0x02, 0x00, 0x00, 0x00,
        0xAA, 0x00, 0x00, 0x00, 0x01, 0x00, 0x01, 0x00, 0x02, 0x00, 0x00, 0x00, 0xBB, 0x00, 0x00, 0x00,
        0x02, 0x00, 0x02, 0x00, 0x02, 0x00, 0x00, 0x00, 0xCC, 0x00, 0x00, 0x00, 0x03, 0x00, 0x03, 0x00,
        0xA0, 0xC0, 0xF7, 0x6A, 0xC0, 0xDC, 0xF7, 0x6A, 0x02, 0x00, 0x00, 0x00, 0x80, 0x01, 0xF5, 0x6A,
        0xA0, 0x1D, 0xF5, 0x6A, 0x01, 0x00, 0x00, 0x00, 0x50, 0x99, 0xF6, 0x6A, 0x70, 0xB5, 0xF6, 0x6A,
        0x01, 0x00, 0x00, 0x00, 0xD0, 0x8D, 0xFA, 0x6A, 0xF0, 0xA9, 0xFA, 0x6A, 0x01, 0x00, 0x00, 0x00,
        0xD0, 0x30, 0xFD, 0x6A, 0xF0, 0x4C, 0xFD, 0x6A, 0x01, 0x00, 0x00, 0x00
    };

    constexpr uint32_t MAX_BYTES = 65536;
    constexpr Header HEADER = parseHeader(SAMPLE, sizeof(SAMPLE), MAX_BYTES);

    // Unix times (Asia/Manila) used below; the copy covers 2026-11-12 to 2026-11-19.
    constexpr uint32_t NOV11_235959 = 1794412799;
    constexpr uint32_t NOV12_0000 = 1794412800;
    constexpr uint32_t NOV12_0700 = 1794438000;
    constexpr uint32_t NOV12_0900 = 1794445200;
    constexpr uint32_t NOV12_0930 = 1794447000;
    constexpr uint32_t NOV12_1000 = 1794448800;
    constexpr uint32_t NOV13_1200 = 1794542400;
    constexpr uint32_t NOV14_1100 = 1794625200;
    constexpr uint32_t NOV14_1200 = 1794628800;
    constexpr uint32_t NOV19_235959 = 1795103999;
    constexpr uint32_t NOV20_0000 = 1795104000;

    struct Lookup {
        bool listed = false;
        uint32_t userId = 0;
        Decision decision{};
    };

    // The controller's lookup (AccessCache.cpp), on the whole copy in memory.
    constexpr Lookup lookup(uint8_t type, uint16_t slot, const char *uidText, uint32_t now, Mode mode = Mode::Auto) {
        Lookup result{};
        uint8_t uid[5] = {};
        if (type == TYPE_CARD && !parseUid(uidText, 10, uid)) return result;
        for (uint16_t i = 0; i < HEADER.credentials; ++i) {
            const uint8_t *record = SAMPLE + HEADER.credentialsOffset() + i * RECORD_BYTES;
            if (!credentialMatches(record, type, slot, uid)) continue;
            const Person person = parsePerson(SAMPLE + HEADER.peopleOffset() + credentialPerson(record) * RECORD_BYTES);
            result.listed = true;
            result.userId = person.userId;
            result.decision = decide(HEADER, person, credentialFlags(record),
                SAMPLE + HEADER.windowsOffset() + person.firstWindow * RECORD_BYTES, person.windowCount, now, mode);
            return result;
        }
        return result;
    }
    constexpr Lookup finger(uint16_t slot, uint32_t now, Mode mode = Mode::Auto) { return lookup(TYPE_FINGER, slot, "", now, mode); }
    constexpr Lookup card(const char *uid, uint32_t now, Mode mode = Mode::Auto) { return lookup(TYPE_CARD, 0, uid, now, mode); }

    // Format and integrity.
    constexpr uint8_t CRC_CHECK[] = {'1', '2', '3', '4', '5', '6', '7', '8', '9'};
    static_assert(crc32(0, CRC_CHECK, sizeof(CRC_CHECK)) == 0xCBF43926UL, "CRC-32 must match zlib / PHP crc32().");
    static_assert(HEADER.valid && HEADER.totalBytes() == sizeof(SAMPLE), "The backend copy must parse.");
    static_assert(crc32(0, SAMPLE + HEADER_BYTES, HEADER.payloadSize) == HEADER.payloadCrc, "The payload CRC must match the header.");
    static_assert(HEADER.people == 4 && HEADER.credentials == 6 && HEADER.windows == 5, "Record counts.");
    static_assert(HEADER.validFrom == NOV12_0000 && HEADER.validUntil == NOV20_0000, "Today and the next 7 days.");
    static_assert(!parseHeader(SAMPLE, sizeof(SAMPLE), sizeof(SAMPLE) - 1).valid, "A copy larger than the storage slot is refused.");
    static_assert(!parseHeader(SAMPLE, HEADER_BYTES - 1, MAX_BYTES).valid, "A short header is refused.");

    // Faculty member (finger slot 7, card BB00000002): regular windows.
    static_assert(finger(7, NOV12_0900).listed && finger(7, NOV12_0900).userId == 2, "Slot 7 belongs to user 2.");
    static_assert(finger(7, NOV12_0900).decision.granted && finger(7, NOV12_0900).decision.kind == Kind::Regular
        && finger(7, NOV12_0900).decision.endEpoch == NOV12_1000 && finger(7, NOV12_0900).decision.secondsRemaining == 3600,
        "Inside 08:00-10:00: granted until 10:00 (for the 15-minute reminder).");
    static_assert(card("bb00000002", NOV12_0900).decision.granted, "The same person's card, any letter case.");
    static_assert(!finger(7, NOV12_0700).decision.granted && finger(7, NOV12_0700).decision.reason == Reason::NotStarted, "07:00: not started yet.");
    static_assert(!finger(7, NOV12_1000).decision.granted && finger(7, NOV12_1000).decision.reason == Reason::Expired, "10:00 is the end: expired.");
    static_assert(finger(7, NOV13_1200).decision.reason == Reason::NotStarted, "Friday 12:00, before the 13:00 window.");
    static_assert(finger(7, NOV14_1100).decision.reason == Reason::NoSchedule, "Saturday: no schedule.");

    // Student (card AA00000001): the approved override only.
    static_assert(card("AA00000001", NOV14_1100).decision.granted && card("AA00000001", NOV14_1100).decision.kind == Kind::Override
        && card("AA00000001", NOV14_1100).decision.endEpoch == NOV14_1200, "Inside the approved override.");
    static_assert(card("AA00000001", NOV12_0930).decision.reason == Reason::NoSchedule, "A student's regular schedule never opens the door.");

    // Admin and emergency cards: any time. Unlisted credentials are not found.
    static_assert(card("CC00000003", NOV19_235959).decision.kind == Kind::PermanentOverride && card("CC00000003", NOV19_235959).userId == 3, "Admin: any time.");
    static_assert(card("9900000099", NOV12_0700).decision.kind == Kind::PermanentOverride && card("9900000099", NOV12_0700).userId == 0, "Emergency card: any time.");
    static_assert(!card("DD00000004", NOV12_0900).listed && !card("FF00000006", NOV12_0900).listed && !finger(9, NOV12_0900).listed,
        "Inactive accounts, duplicate cards and unusable slots are not listed.");
    static_assert(!card("XYZ", NOV12_0900).listed, "A malformed UID is never listed.");

    // Scheduling Off: any listed credential. Outside the copy's days: unusable.
    static_assert(finger(7, NOV14_1100, Mode::Off).decision.granted && finger(7, NOV14_1100, Mode::Off).decision.kind == Kind::ScheduleOff, "Off.");
    static_assert(finger(7, NOV11_235959).decision.reason == Reason::OutOfRange && finger(7, NOV20_0000).decision.reason == Reason::OutOfRange,
        "Before or after the covered days the copy is not used.");
}
